head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > displayFormat]<br/>SearchBox 컴포넌트의 포커스가 해제된 상태일때 입력값이 표시되는 포맷을 마스크 문자로 설정합니다.",
    "validation" : [
        "displayFormatter 속성이 설정되면 해당 속성은 무시됩니다.",
        "dataType 속성값을 text 로 설정 시 '#' 마스크 문자를 사용하여 포맷 설정합니다.",
        "dataType 속성값이 text 일때 마스크 문자는 오른쪽 문자부터 매칭되며 '#' 이외의 문자는 그대로 적용됩니다.",
        "dataType 속성값을 number 로 설정 시 '#', '0', ',', '.' 마스크 문자를 사용하여 포맷 설정합니다.",
        "dataType 속성값이 number 일때 '#' 마스크는 해당 위치에 숫자가 있으면 표시되고 없으면 표시되지 않습니다.",
        "dataType 속성값이 number 일때 '0' 마스크는 소수 영역에만 사용되며, 해당 위치에 숫자가 있으면 표시되고 없으면 0 으로 표시됩니다.",
        "dataType 속성값이 number 일때 ',', '.' 마스크는 천단위 구분자와 소수점 위치로 표시됩니다.",
        "dataType 속성값이 number 일때 소수값이 있을때 마스크 문자 오른쪽에 '[round]', '[floor]', '[ceil]' 을 설정하여 반올림, 버림, 올림을 적용할 수 있습니다.",
        "dataType 속성값이 number 일때 마스크 포맷 왼쪽과 오른쪽의 일반문자는 그대로 적용됩니다.",
        "dataType 속성값이 number 일때 내부 텍스트에 부호와 숫자가 아닌 값이 포함되면 'NaN' 으로 표시됩니다.",
        "dataType 속성값을 date 로 설정 시 'y', 'M', 'd', 'E' 마스크 문자를 사용하여 포맷 설정합니다.",
        "dataType 속성값이 date 일때 'yyyy' 마스크는 년도와 매칭되며 네자리로 설정합니다.",
        "dataType 속성값이 date 일때 'MM' 마스크는 월과 매칭되며 두자리로 설정합니다.",
        "dataType 속성값이 date 일때 'dd' 마스크는 일과 매칭되며 두자리로 설정합니다.",
        "dataType 속성값이 date 일때 'E' 마스크는 요일과 매칭됩니다.",
        "dataType 속성값이 date 일 때 displayFormat 속성을 설정하지 않으면 'yyyy-MM-dd' 가 적용됩니다.",
        "dataType 속성값을 time 로 설정 시 'H', 'm', 's' 마스크 문자를 사용하여 포맷 설정합니다.",
        "dataType 속성값이 time 일때 'HH' 마스크는 시와 매칭되며 두자리로 설정합니다.",
        "dataType 속성값이 time 일때 'mm' 마스크는 분과 매칭되며 두자리로 설정합니다.",
        "dataType 속성값이 time 일때 'ss' 마스크는 초와 매칭되며 두자리로 설정합니다.",
        "dataType 속성값이 time 일 때 displayFormat 속성을 설정하지 않으면 'HH:mm' 이 적용됩니다.",
        "SearchBox 의 실제 입력값은 displayFormat 포맷이 제거된 상태로 저장됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.get_text_display = function(target) {
    let rtn = '';
    let inputElem = target.render.querySelector("input");

    if (inputElem) {
        rtn = inputElem.value;
        wf_body_bottom.getObj("scwin").setReturnValue("text(display) : " + rtn);
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("input element not found");
    }
}



scwin.get_value = function(target) {
    wf_body_bottom.getObj("scwin").setReturnValue("getValue : " + target.getValue());
}



// 사용자 정의 displayFormatter
scwin.fn_dpformatter = function(val) {
    return "language -> " + val;
};



// target1 : dataType=text, displayFormat=#:##-##, 입력값=langkoKR -> lang:ko-KR
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("langkoKR");
};

scwin.btn_getText1_onclick = function (e) {
    scwin.get_text_display(target1);
}

scwin.btn_getValue1_onclick = function (e) {
    scwin.get_value(target1);
}

// target2 : dataType=number, displayFormat=#,###, 입력값=123456789 -> 123,456,789
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("123456789");
};

scwin.btn_getText2_onclick = function (e) {
    scwin.get_text_display(target2);
}

scwin.btn_getValue2_onclick = function (e) {
    scwin.get_value(target2);
}

// target3 : dataType=number, displayFormat=₩ #,###.#0[floor] won, 입력값=-1234.5678 -> ₩ -1,234.56 won
scwin.btn_setValue3_onclick = function (e) {
